/// <summary>
/// Update the custom field once the value is updated to completed
/// </summary>
[ExtensionOf(tableStr(WMSShipment))]
final class METWMSShipment_Extension
{
}

Method.Source:
/// <summary>
/// Data event handler for WMSOrderTransTable to update the custom field when status is updated to completed
/// </summary>
/// <param name="sender">type object</param>
/// <param name="e">DataEvent type object</param>
public void ship(NoYes _generateBillOfLading)
{
    WMSOrderTrans orderTrans;

    next ship(_generateBillOfLading); // Run standard shipping logic first

    update_recordset orderTrans
        setting METPickedQtyProcessed = NoYes::Yes
        where orderTrans.ShipmentId == this.ShipmentId
           && (orderTrans.ExpeditionStatus == WMSExpeditionStatus::Complete || 
              orderTrans.expeditionStatus == WMSExpeditionStatus::Cancelled)
           && orderTrans.METPickedQtyProcessed != NoYes::Yes;
}
